#pragma once
#include <stdint.h>

// Generated by tools/build.py from data/cameras.json. Do not edit by hand.
// Source: SPF enforcement camera lists, approach paths reviewed in the path editor.

enum class CameraType : uint8_t {
    RedLight = 1,
    FixedSpeed = 2,
    MobileSpeed = 3,
    AverageSpeed = 4,
    LaserSpeed = 5,
    Violation = 6,
};

inline const char* cameraTypeLabel(CameraType type) {
    switch (type) {
        case CameraType::RedLight: return "Red light camera";
        case CameraType::FixedSpeed: return "Speed camera";
        case CameraType::MobileSpeed: return "Mobile speed camera";
        case CameraType::AverageSpeed: return "Average speed zone";
        case CameraType::LaserSpeed: return "Police laser camera";
        case CameraType::Violation: return "Traffic violation camera";
    }
    return "Camera";
}

// Micro-degrees. A camera's points run from the start of its approach to the camera.
struct CameraPoint {
    int32_t latE6;
    int32_t lonE6;
};

struct Camera {
    uint16_t id;          // camera id in data/cameras.json
    CameraType type;
    uint8_t pointCount;   // points in kCameraPoints for this camera
    uint16_t firstPoint;  // index of its first point in kCameraPoints
};

